def powers(x, n):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, p], axis=1) for p in combinations_with_replacement(range(x.shape[1]), n)])

def ridge(x, v, kind):
    w = x @ v[:4]
    a = np.exp(v[4])
    if kind == 'p':
        return np.c_[w ** 3, w ** 4, w ** 5]
    if kind == 'sin':
        return np.sin(a * w + v[5])[:, None]
    if kind == 'tanh':
        return np.tanh(a * w + v[5])[:, None]
    if kind == 'rat':
        return (1 / (1 + (a * w + v[5]) ** 2))[:, None]
    if kind == 'quot':
        return np.c_[np.ones(len(x)), x] / (1 + (a * w[:, None] + v[5]) ** 2)
    if kind == 'norm':
        return (1 / (1 + a * np.sum((x - v[:4]) ** 2, axis=1)))[:, None]
    if kind == 'soft':
        return ((a * w + v[5]) / (1 + abs(a * w + v[5])))[:, None]
